package com.lianxibu.site.service.sources;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import com.lianxibu.site.domain.sources.OwnerSourceSnapshot;
import java.nio.file.*;import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;
class OwnerSourceReadServiceTest {
 private static final Actor OWNER=new Actor("fictional-owner","owner");
 private static final JsonMapper JSON=JsonMapper.builder().build();
 private OwnerSourceSnapshot snapshot(){return new OwnerSourceSnapshot("fictional-source","article","Fictional",0L,0L,"disabled","news_tech",null,null,null);}
 @Test void knownZeroAndNullConfigRemainSeparateAndOneExactReadOccurs(){int[] calls={0};var service=new OwnerSourceReadService(id->{calls[0]++;assertEquals("fictional-source",id);return snapshot();});var data=service.read(OWNER,"fictional-source");assertEquals(0L,data.get("revision"));assertNull(data.get("draft_config"));assertNull(data.get("effective_config"));assertEquals(1,calls[0]);assertThrows(UnsupportedOperationException.class,()->data.put("revision",1));assertEquals(9,data.size());}
 @Test void ownerAndIdentityAreCheckedBeforeStorage(){int[] calls={0};var service=new OwnerSourceReadService(id->{calls[0]++;return snapshot();});for(var actor:Arrays.asList(null,new Actor("fictional-user","user"),new Actor("","owner")))assertThrows(OwnerSourceReadService.Denied.class,()->service.read(actor,"fictional-source"));for(String id:List.of("","bad\n","x".repeat(81)))assertThrows(IllegalArgumentException.class,()->service.read(OWNER,id));assertEquals(0,calls[0]);}
 @Test void missingAndUnmappedMetadataNeverBecomeGuessedDefaults(){assertThrows(OwnerSourceReadService.Missing.class,()->new OwnerSourceReadService(id->null).read(OWNER,"fictional-source"));for(var row:List.of(new OwnerSourceSnapshot("fictional-source","article","Fictional",null,0L,"disabled","news_tech",null,null,null),new OwnerSourceSnapshot("fictional-source","article","Fictional",0L,0L,"disabled",null,null,null,null),new OwnerSourceSnapshot("fictional-source","catalog","Fictional",0L,0L,"disabled","news_tech",null,null,null)))assertThrows(OwnerSourceReadService.MappingRequired.class,()->new OwnerSourceReadService(id->row).read(OWNER,"fictional-source"));}
 @Test void allTwentyPublishedProtocolVectorsClassifyWithoutAdmissionGuessing()throws Exception{var rows=JSON.readTree(Files.readString(Path.of("../contracts/owner-source-wire-examples.json"))).get("cases");assertEquals(20,rows.size());for(var row:rows){Map<String,Object> data=JSON.convertValue(row.get("data"),Map.class);if(row.get("valid").booleanValue())OwnerSourceReadService.validateProjection(data,"fictional-source");else assertThrows(OwnerSourceReadService.Unavailable.class,()->OwnerSourceReadService.validateProjection(data,"fictional-source"),row.get("name").textValue());}}
 @Test void staleIdentityAndRawConfigNeverReachWire(){var service=new OwnerSourceReadService(id->new OwnerSourceSnapshot("fictional-other","article","Fictional",0L,0L,"disabled","news_tech",null,null,null));assertThrows(OwnerSourceReadService.Unavailable.class,()->service.read(OWNER,"fictional-source"));var raw=new OwnerSourceSnapshot("fictional-source","article","Fictional",0L,0L,"disabled","news_tech","{\"token\":\"fictional\"}",null,null);assertFalse(raw.toString().contains("token"));assertThrows(OwnerSourceReadService.Unavailable.class,()->new OwnerSourceReadService(id->raw).read(OWNER,"fictional-source"));}
 @Test void storageFailureHasNoPrivateDiagnostic(){var service=new OwnerSourceReadService(id->{throw new IllegalStateException("fictional private diagnostic");});var error=assertThrows(OwnerSourceReadService.Unavailable.class,()->service.read(OWNER,"fictional-source"));assertFalse(error.getMessage().contains("diagnostic"));assertNull(error.getCause());}
 @Test void draftAndEffectiveConfigsRemainDistinctFrozenAndExpiredStillReadable()throws Exception{var vector=JSON.readTree(Files.readString(Path.of("../contracts/owner-source-wire-examples.json"))).get("cases").get(0).get("data").get("draft_config");String raw=JSON.writeValueAsString(vector);var row=new OwnerSourceSnapshot("fictional-source","article","Fictional",0L,0L,"disabled","news_tech",raw,null,java.time.Instant.parse("2026-01-01T00:00:00Z"));var v=new OwnerSourceReadService(id->row).read(OWNER,"fictional-source");assertNotNull(v.get("draft_config"));assertNull(v.get("effective_config"));assertEquals("2026-01-01T00:00:00.000000Z",v.get("config_valid_until"));Map draft=(Map)v.get("draft_config");assertThrows(UnsupportedOperationException.class,()->draft.put("adapter","fictional changed"));assertThrows(UnsupportedOperationException.class,()->((List)draft.get("entry_urls")).add("fictional"));}
 @Test void unknownReferenceAndAuthenticatedEntryAreNotSecretValuesToReturn()throws Exception{var config=JSON.readTree(Files.readString(Path.of("../contracts/owner-source-wire-examples.json"))).get("cases").get(0).get("data").get("draft_config");for(String raw:List.of(JSON.writeValueAsString(config).replace("https://example.invalid/feed","https://fictional-user:fictional-pass@example.invalid/feed"),JSON.writeValueAsString(config).replace("\"auth_secret_ref\":null","\"auth_secret_ref\":\"fictional-token-value\""))){var row=new OwnerSourceSnapshot("fictional-source","article","Fictional",0L,0L,"disabled","news_tech",raw,null,null);assertThrows(OwnerSourceReadService.Unavailable.class,()->new OwnerSourceReadService(id->row).read(OWNER,"fictional-source"));}}
 @Test void actualAdmissionStoredInstantNormalizesOnlyAtTheWireBoundary(){var expiry=java.time.Instant.parse("2026-10-03T00:00:00Z");var config=new SourcesService.SourceConfig("fictional-rss",List.of("https://example.invalid/feed"),"fictional-guid","fictional-window","fictional-v1",20,1024,List.of("example.invalid"),expiry,null);String raw=new SourceAdmissionPolicy(java.time.Clock.fixed(java.time.Instant.parse("2026-01-01T00:00:00Z"),java.time.ZoneOffset.UTC)).validatedConfigJson(config);assertTrue(raw.contains("2026-10-03T00:00:00Z"));var row=new OwnerSourceSnapshot("fictional-source","article","Fictional",1L,1L,"disabled","news_tech",raw,null,null);var value=new OwnerSourceReadService(id->row).read(OWNER,"fictional-source");assertEquals("2026-10-03T00:00:00.000000Z",((Map)value.get("draft_config")).get("valid_until"));}
}
